PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,admin INTEGER NOT NULL DEFAULT 0,disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,code TEXT UNIQUE NOT NULL,municipality TEXT NOT NULL DEFAULT '',has_project INTEGER,phase INTEGER NOT NULL DEFAULT 0,paused INTEGER NOT NULL DEFAULT 0,pause_reason TEXT,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS participations(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),company_id TEXT NOT NULL REFERENCES companies(id),role TEXT NOT NULL,activity TEXT,UNIQUE(project_id,company_id));
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),project_id TEXT NOT NULL REFERENCES projects(id),company_id TEXT REFERENCES companies(id),role TEXT NOT NULL,categories TEXT NOT NULL,permissions TEXT NOT NULL,UNIQUE(user_id,project_id,company_id));
CREATE TABLE IF NOT EXISTS workers(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),name TEXT NOT NULL,trade TEXT,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS worker_assignments(worker_id TEXT NOT NULL REFERENCES workers(id),project_id TEXT NOT NULL REFERENCES projects(id),PRIMARY KEY(worker_id,project_id));
CREATE TABLE IF NOT EXISTS equipment(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),name TEXT NOT NULL,kind TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS equipment_assignments(equipment_id TEXT NOT NULL REFERENCES equipment(id),project_id TEXT NOT NULL REFERENCES projects(id),PRIMARY KEY(equipment_id,project_id));
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),user_id TEXT REFERENCES users(id),name TEXT NOT NULL,function TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,sensitive INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rule_templates(id TEXT PRIMARY KEY,version INTEGER NOT NULL,name TEXT NOT NULL,scope TEXT NOT NULL,category TEXT NOT NULL,condition TEXT NOT NULL,classification TEXT NOT NULL DEFAULT 'pendiente_revision',source TEXT,review_date TEXT,approved_by TEXT,blocking INTEGER NOT NULL DEFAULT 0,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS requirements(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),company_id TEXT REFERENCES companies(id),worker_id TEXT REFERENCES workers(id),equipment_id TEXT REFERENCES equipment(id),rule_id TEXT REFERENCES rule_templates(id),rule_version INTEGER,name TEXT NOT NULL,category TEXT NOT NULL,snapshot TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pendiente',blocking INTEGER NOT NULL DEFAULT 0,applicability TEXT NOT NULL DEFAULT 'pendiente_revision',reason TEXT,author TEXT,UNIQUE(project_id,company_id,worker_id,equipment_id,rule_id));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),company_id TEXT REFERENCES companies(id),worker_id TEXT REFERENCES workers(id),requirement_id TEXT REFERENCES requirements(id),title TEXT NOT NULL,category TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}',created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),number INTEGER NOT NULL,storage_key TEXT NOT NULL UNIQUE,filename TEXT NOT NULL,mime TEXT NOT NULL,hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'recibido',expires TEXT,provenance TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(document_id,number));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),action TEXT NOT NULL,reason TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS signature_requests(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),mode TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pendiente',provider TEXT NOT NULL,expires TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS signers(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES signature_requests(id),user_id TEXT NOT NULL REFERENCES users(id),position INTEGER NOT NULL,function TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pendiente',token_hash TEXT NOT NULL UNIQUE,revoked INTEGER NOT NULL DEFAULT 0,signed_at TEXT,reason TEXT,UNIQUE(request_id,user_id));
CREATE TABLE IF NOT EXISTS signature_archives(request_id TEXT PRIMARY KEY REFERENCES signature_requests(id),storage_key TEXT NOT NULL,evidence_key TEXT NOT NULL,hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),company_id TEXT REFERENCES companies(id),requirement_id TEXT UNIQUE REFERENCES requirements(id),title TEXT NOT NULL,actor TEXT,owner TEXT,due TEXT,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'pendiente',origin TEXT NOT NULL DEFAULT 'manual',details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS dependencies(task_id TEXT NOT NULL REFERENCES tasks(id),depends_on TEXT NOT NULL REFERENCES tasks(id),PRIMARY KEY(task_id,depends_on),CHECK(task_id<>depends_on));
CREATE TABLE IF NOT EXISTS milestones(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,date TEXT,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,event_key TEXT UNIQUE NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id),company_id TEXT REFERENCES companies(id),message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,email TEXT NOT NULL,name TEXT NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id),company_id TEXT REFERENCES companies(id),role TEXT NOT NULL,categories TEXT NOT NULL,permissions TEXT NOT NULL,expires TEXT NOT NULL,used_at TEXT,revoked INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,user_id TEXT,project_id TEXT,company_id TEXT,action TEXT NOT NULL,entity_id TEXT,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,event_key TEXT UNIQUE NOT NULL,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,adapter TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'prueba_no_enviado',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,window TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS docs_project ON documents(project_id,company_id,category);
CREATE INDEX IF NOT EXISTS grants_user ON grants(user_id,project_id);
CREATE INDEX IF NOT EXISTS audit_project ON audit(project_id,created_at);
